   763		name = nameVersion[:verIndex]
   764		ver = nameVersion[verIndex+1:]
   765		if name == "" || ver == "" || strings.HasPrefix(name, "-") || strings.HasSuffix(name, "-") || strings.Contains(name, "--") {
   766			return invalid()
   767		}
   768		return name, ver, rel, epoch, arch, nil
   769	}
