   771	func (o *redhatBase) parseRpmQfLine(line string) (pkg *models.Package, ignored bool, err error) {
   772		for _, suffix := range []string{
   773			"Permission denied",
   774			"is not owned by any package",
   775			"No such file or directory",
   776		} {
   777			if strings.HasSuffix(line, suffix) {
   778				return nil, true, nil
   779			}
   780		}
   781		pkg, _, err = o.parseInstalledPackagesLine(line)
   782		return pkg, false, err
   783	}
