   794	func (o *redhatBase) scanUpdatablePackages() (models.Packages, error) {
   795		isDnf := o.exec(util.PrependProxyEnv(`repoquery --version | grep dnf`), o.sudo.repoquery()).isSuccess()
   796		cmd := `repoquery --all --pkgnarrow=updates --qf='%{NAME} %{EPOCH} %{VERSION} %{RELEASE} %{REPO}'`
   797		if isDnf {
   798			cmd = `repoquery --upgrades --qf='%{NAME} %{EPOCH} %{VERSION} %{RELEASE} %{REPONAME}' -q`
   799		}
   800		for _, repo := range o.getServerInfo().Enablerepo {
   801			cmd += " --enablerepo=" + repo
   802		}
   803	
   804		r := o.exec(util.PrependProxyEnv(cmd), o.sudo.repoquery())
   805		if !r.isSuccess() {
   806			return nil, xerrors.Errorf("Failed to SSH: %s", r)
   807		}
   808	
   809		// Collect Updatable packages, installed, candidate version and repository.
   810		return o.parseUpdatablePacksLines(r.Stdout)
   811	}
   812	
   813	// parseUpdatablePacksLines parse the stdout of repoquery to get package name, candidate version
   814	func (o *redhatBase) parseUpdatablePacksLines(stdout string) (models.Packages, error) {
   815		updatable := models.Packages{}
   816		lines := strings.Split(stdout, "\n")
   817		for _, line := range lines {
   818			if len(strings.TrimSpace(line)) == 0 {
   819				continue
   820			} else if strings.HasPrefix(line, "Loading") {
   821				continue
   822			}
   823			pack, err := o.parseUpdatablePacksLine(line)
   824			if err != nil {
   825				return updatable, err
   826			}
   827			updatable[pack.Name] = pack
   828		}
   829		return updatable, nil
   830	}
   831	
   832	func (o *redhatBase) parseUpdatablePacksLine(line string) (models.Package, error) {
   833		fields := strings.Fields(line)
   834		if len(fields) < 5 {
   835			return models.Package{}, xerrors.Errorf("Unknown format: %s, fields: %s", line, fields)
   836		}
   837	
   838		ver := formatRPMVersion(fields[1], fields[2], "")
   839	
   840		repos := strings.Join(fields[4:], " ")
   841	
   842		p := models.Package{
   843			Name:       fields[0],
   844			NewVersion: ver,
   845			NewRelease: fields[3],
   846			Repository: repos,
   847		}
   848		return p, nil
   849	}
